import{_ as e,o as a,c as o,ah as d}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Document templates","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/gestion-documentaire/modeles.md","filePath":"src/en/guide/gestion-documentaire/modeles.md"}'),r={name:"en/guide/gestion-documentaire/modeles.md"};function n(s,t,i,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="document-templates" tabindex="-1">Document templates <a class="header-anchor" href="#document-templates" aria-label="Permalink to &quot;Document templates&quot;">​</a></h1><p>A <strong>template</strong> is a document the school writes once and then produces for anyone: a certificate of enrolment, an employment certificate… When it is produced, ERA fills in its fields from the person&#39;s record, lays it out on the school&#39;s letterhead and files it in their file.</p><p>Templates are kept by an administrator or the document manager, from the <strong>Documents</strong> space → <strong>Templates</strong>.</p><h2 id="write-a-template" tabindex="-1">Write a template <a class="header-anchor" href="#write-a-template" aria-label="Permalink to &quot;Write a template&quot;">​</a></h2><ol><li>Click <strong>New template</strong>.</li><li>To start from a ready-made text, click <strong>Start from an example</strong>: ERA fills in a certificate of enrolment, which you adapt.</li><li>Give it a <strong>Name</strong>: it is also the title printed at the top of the document.</li><li>Choose the type it is <strong>Filed under</strong>. That type&#39;s file (student, employee or school) decides which fields are offered.</li><li>Write the <strong>Text</strong>. Leave a blank line between two paragraphs.</li><li>To insert a field, place the cursor, then click the field under <strong>Insert a field</strong>. It is written in braces, for example <code>{student.full_name}</code>.</li><li>Click <strong>Save</strong>.</li></ol><p>The letterhead (the school&#39;s logo, name and contact details), the title and the &quot;The management&quot; signature space are added on their own: do not write them in the text.</p><p>If the text holds a field the type&#39;s file does not offer (an employee&#39;s field in a student&#39;s certificate, a typo), ERA refuses to save and names the field at fault.</p><h3 id="the-fields" tabindex="-1">The fields <a class="header-anchor" href="#the-fields" aria-label="Permalink to &quot;The fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Filled in with</th><th>Files</th></tr></thead><tbody><tr><td>School name</td><td>the application&#39;s name</td><td>all</td></tr><tr><td>School address</td><td>the address in <strong>App settings</strong> → <strong>Receipt branding</strong></td><td>all</td></tr><tr><td>Today&#39;s date</td><td>the date the document is produced</td><td>all</td></tr><tr><td>School year</td><td>the current school year</td><td>all</td></tr><tr><td>Full name, Last name, First names</td><td>the student&#39;s record</td><td>student</td></tr><tr><td>Date and place of birth</td><td>the student&#39;s record</td><td>student</td></tr><tr><td>Registration number</td><td>the student&#39;s registration number</td><td>student</td></tr><tr><td>Class, Site</td><td>their enrolment for the current year</td><td>student</td></tr><tr><td>Name, Position, Hire date, Site</td><td>the employee&#39;s record</td><td>employee</td></tr></tbody></table><p>Information missing from the record leaves a blank in the document: complete the record before producing it.</p><h2 id="produce-a-document" tabindex="-1">Produce a document <a class="header-anchor" href="#produce-a-document" aria-label="Permalink to &quot;Produce a document&quot;">​</a></h2><ol><li>Open the person&#39;s file.</li><li>Click <strong>Produce from a template</strong>. The button only shows when a template exists for a type you may file in this file.</li><li>Choose the <strong>Template</strong>, then click <strong>Produce</strong>.</li></ol><p>The document is filed at once in the file, under the template&#39;s type, dated today. It is <strong>validated</strong> straight away if you may validate that type; otherwise it waits to be checked like any filing. Its text can be found by the search on the <strong>Documents</strong> page.</p><p>If the type is shared with families, the validated document also shows in the family&#39;s and the student&#39;s portal.</p><h2 id="edit-or-delete-a-template" tabindex="-1">Edit or delete a template <a class="header-anchor" href="#edit-or-delete-a-template" aria-label="Permalink to &quot;Edit or delete a template&quot;">​</a></h2><p><strong>Edit</strong> changes the text for the next documents produced; those already produced do not change. <strong>Delete</strong> removes the template; documents already produced stay in their files. Deleting a document type also deletes its templates.</p>',16)])])}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
